package com.healthcompanion.controller;
import com.healthcompanion.dto.ChatDtos.*; import com.healthcompanion.service.ChatService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/chat") public class ChatController {private final ChatService s; public ChatController(ChatService s){this.s=s;} @PostMapping("/conversations") @ResponseStatus(HttpStatus.CREATED) public ConversationResponse create(Authentication a,@Valid @RequestBody ConversationRequest r){return s.create(a.getName(),r);} @GetMapping("/conversations") public List<ConversationResponse> list(Authentication a){return s.list(a.getName());} @GetMapping("/conversations/{id}/messages") public List<MessageResponse> messages(Authentication a,@PathVariable Long id){return s.messages(a.getName(),id);} @PostMapping("/conversations/{id}/messages") public List<MessageResponse> send(Authentication a,@PathVariable Long id,@Valid @RequestBody MessageRequest r){return s.send(a.getName(),id,r);} @DeleteMapping("/conversations/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable Long id){s.delete(a.getName(),id);} }
